package ama.storage;
import ama.transcript.*;import ama.config.*;import ama.config.json.*;import ama.minutes.contract.*;import ama.contract.MinutesContracts.*;import java.util.*;import java.time.*;import static org.junit.jupiter.api.Assertions.*;
/** Structural frozen-final fixture over a real candidate. It does not install Task11 or attest readiness. */
class Task09GenerationFinalReaderIT extends Task09GenerationReviewReaderIT {
 @Override void afterReview(Map<String,Object> candidate,JdbcMinutesFactsReader.Snapshot restored,String review)throws Exception {
  var root=j.queryForMap("SELECT * FROM meeting WHERE id=?",meeting);String roster=UUID.randomUUID().toString(),confirmation=UUID.randomUUID().toString();j.update("INSERT INTO roster_revision(id,meeting_id,revision,state,confirmed_at,confirmed_by) VALUES (?,?,2,'CONFIRMED',UTC_TIMESTAMP(6),?)",roster,meeting,owner);j.update("INSERT INTO roster_member(roster_id,member_id,enterprise_id,display_name,member_kind) VALUES (?,?,?,'Frozen original owner','ENTERPRISE')",roster,UUID.randomUUID().toString(),owner);String time=java.time.format.DateTimeFormatter.ofPattern("uuuu-MM-dd'T'HH:mm:ss.SSSSSS'Z'").format(LocalDateTime.now(ZoneOffset.UTC));var data=new LinkedHashMap<String,Object>();data.put("id",confirmation);data.put("meeting_id",meeting);data.put("meeting_revision",4L);data.put("info_revision_id",root.get("info_revision_id"));data.put("roster_revision_id",roster);data.put("transcript_confirmation_id",root.get("transcript_confirmation_id"));data.put("minutes_revision_id",candidate.get("minutes_revision_id"));data.put("material_snapshot_id",null);data.put("element_set_id",candidate.get("element_set_id"));data.put("template_revision_id",root.get("template_revision_id"));data.put("exclusion_revision_id",root.get("exclusion_revision_id"));data.put("source_manifest_hash","0".repeat(64));data.put("input_fingerprint",candidate.get("input_fingerprint"));data.put("confirmed_by",owner);data.put("confirmed_at",time);
  var rows=new ArrayList<>(restored.facts().rows());rows.add(row(Table.FINAL_CONFIRMATION,data));rows.add(row(Table.FINAL_RESULT_REVIEW,Map.of("confirmation_id",confirmation,"review_id",review)));var old=restored.facts();var facts=new StoredProvenanceFacts(rows,old.files(),old.configurations(),old.evidenceAnchors(),old.taskSpecs(),old.reviewScopes(),old.taskFacts(),250000);var snapshot=snapshot();var refs=new GenerationArchiveRefs(facts,snapshot.index(),new StrictProcessingManifestReader(),B,graphBudget,()->false).finalSources(confirmation);var raw=snapshot.loadClosure(refs,B,0,()->false);var config=facts.configurations().stream().filter(c->c.inputId().equals(candidate.get("input_id"))).findFirst().orElseThrow();String hash=new ResultHashProfiles(new ConfigBindings(new StrictConfigArchiveReader(),new StrictProcessingManifestReader()),raw,B).finalSources(new FinalFacts(confirmation,facts),config.profiles().definition(ProfileKind.FINAL_SOURCES),graphBudget,()->false);data.put("source_manifest_hash",hash);var columns=Table.FINAL_CONFIRMATION.columns().stream().map(ColumnSpec::name).toList();var args=columns.stream().map(c->c.equals("confirmed_at")?LocalDateTime.parse(time.substring(0,time.length()-1)):data.get(c)).toArray();j.update("INSERT INTO final_confirmation("+String.join(",",columns)+") VALUES ("+String.join(",",Collections.nCopies(columns.size(),"?"))+")",args);j.update("INSERT INTO final_result_review(confirmation_id,review_id) VALUES (?,?)",confirmation,review);
  var frozen=reader().readOwner(actor(),meeting,"FINAL",confirmation);assertEquals(1,frozen.facts().rows().stream().filter(v->v.table()==Table.FINAL_CONFIRMATION).count());assertEquals(1,frozen.facts().rows().stream().filter(v->v.table()==Table.RESULT_REVIEW).count());assertEquals(hash,frozen.facts().rows().stream().filter(v->v.table()==Table.FINAL_CONFIRMATION).findFirst().orElseThrow().string("source_manifest_hash"));
  // A later malformed current review must not enter the frozen membership or reinterpret its hash.
  String later=UUID.randomUUID().toString();j.update("INSERT INTO result_review SELECT ?,meeting_id,2,review_kind,element_id,minutes_revision_id,target_anchor,?,source_set_hash,hash_profile,outcome,reviewed_by,reviewed_at FROM result_review WHERE id=?",later,"0".repeat(64),review);j.update("INSERT INTO result_review_evidence SELECT ?,evidence_id FROM result_review_evidence WHERE review_id=?",later,review);var again=reader().readOwner(actor(),meeting,"FINAL",confirmation);assertEquals(frozen.facts(),again.facts());assertNull(j.queryForObject("SELECT final_confirmation_id FROM meeting WHERE id=?",String.class,meeting));java.nio.file.Files.writeString(receipt.resolve("actual-structural-final-reader.json"),json.writeValueAsString(Map.of("final",confirmation,"frozenReview",review,"laterExcludedReview",later,"hash",hash,"structuralFixtureOnly",true,"currentRootUnchanged",true)));
 }
 static FullRow row(Table table,Map<String,Object> values){var cells=new ArrayList<Cell>();for(var column:table.columns()){Object value=values.get(column.name());cells.add(value==null?new NullCell():value instanceof Number n?new UIntCell(n.longValue()):new TextCell(value.toString()));}return new FullRow(table,cells);}
}
